import type { Player } from './index';

export const squad: Player[] = [
  // Porteros
  { number: 1, name: 'Nikola Vasilj', position: 'GK', age: 31, club: 'St Pauli', bio: { "es": "El portero viene de familia Vasilj: el padre de Nikola, Vladimir, formó parte de las selecciones de Croacia en los Mundiales de 1998 y 2002, mientras que el propio Nikola representa a Bosnia y Herzegovina, algo que, en esta parte del mundo, nadie encuentra realmente inusual. A diferencia de muchos porteros de élite modernos, Vasilj nunca fue considerado un gran prodigio y pasó años en una rutina de préstamos, fútbol de reserva y acción en ligas inferiores antes de llegar finalmente a la Bundesliga con el club de culto St Pauli. Cuando era niño era un gran admirador de Manuel Neuer y, finalmente, se encontró jugando él mismo contra su ídolo, incluso si su reciente descenso podría poner fin a esas ocasiones. A pesar de su estilo agresivo y sus espectaculares paradas reflejas, sus compañeros lo describen como inusualmente tranquilo y reservado fuera del fútbol.", "en": "Goalkeeping runs in the Vasilj family: Nikola’s father, Vladimir, was part of Croatia’s squads at the 1998 and 2002 World Cups, while Nikola himself represents Bosnia and Herzegovina, something that, in this part of the world, nobody really finds unusual. Unlike many modern elite keepers, Vasilj was never considered a major prodigy and spent years on a treadmill of loans, reserve football and lower league action before finally reaching the Bundesliga with cult club St Pauli. As a child he was a huge admirer of Manuel Neuer, and eventually he found himself playing against his idol himself – even if their recent relegation might put an end to such occasions. Despite his aggressive style and spectacular reflex saves, teammates describe him as unusually calm and reserved away from football." }, special: "Long-term keeper" },
  { number: 12, name: 'Mladen Jurkas', position: 'GK', age: 18, club: 'Borac Banja Luka', bio: { "es": "Las cosas han avanzado rápidamente para este adolescente. El año pasado por estas fechas, Jurkas estaba adquiriendo experiencia en el primer equipo de la segunda división de Bosnia y Herzegovina; Apenas 12 meses después, se encuentra en el avión rumbo al Mundial. Jurkas hizo su debut absoluto con el Borac Banja Luka con sólo 17 años y esta temporada se ha consolidado como el portero titular del club. Borac ganó su cuarto título de liga y mantuvo 16 porterías a cero en 31 apariciones, cifras que inicialmente le valieron un lugar en la lista de reserva de Bosnia para este verano. Pero después de que Osman Hadzikic se lesionara en un amistoso de preparación contra Macedonia del Norte, Jurkas recibió una convocatoria tardía, convirtiendo lo que ya había sido un año extraordinario en algo aún más improbable para el joven de 18 años.", "en": "Things have moved quickly for this teenager. This time last year, Jurkas was gaining first-team experience in Bosnia and Herzegovina’s second tier; barely 12 months later, he finds himself on the plane to the World Cup. Jurkas made his senior debut for Borac Banja Luka at just 17 and this season established himself as the club’s first-choice goalkeeper. Borac won their fourth league title while he kept 16 clean sheets in 31 appearances – numbers that initially earned him a place on Bosnia’s reserve list for this summer. But after Osman Hadzikic got injured in a warm-up friendly against North Macedonia, Jurkas received a late call-up, turning what had already been a remarkable year into something even more improbable for the 18-year-old." }, special: "Late call-up" },
  { number: 22, name: 'Martin Zlomislic', position: 'GK', age: 24, club: 'HNK Rijeka', bio: { "es": "Zlomislic tomó un camino relativamente tranquilo hacia el nivel más alto, construyendo gradualmente su reputación a través de la coherencia en lugar de la exageración. Después de desarrollarse en Siroki Brijeg, se mudó a Rijeka y se estableció como uno de los porteros más confiables del fútbol croata, ayudando al club a negociar carreras por el título y noches europeas. Si bien Nikola Vasilj sigue siendo el número uno indiscutible de Bosnia y Herzegovina, Zlomislic ofrece al equipo una opción de respaldo experimentada y confiable. Rara vez llama mucho la atención, lo que para un portero suele ser una buena señal. Los entrenadores croatas han elogiado a menudo su compostura, su posicionamiento y su capacidad para mantener la calma en los momentos difíciles.", "en": "Zlomislic took a relatively quiet route to the highest level, gradually building his reputation through consistency rather than hype. After developing at Siroki Brijeg, he moved to Rijeka and established himself as one of the more reliable goalkeepers in Croatian football, helping the club negotiate title races and European nights. While Nikola Vasilj remains Bosnia and Herzegovina’s undisputed No 1, Zlomislic offers the squad an experienced and dependable backup option. He rarely attracts much attention, which for a goalkeeper is usually a good sign. Coaches in Croatia have often praised his composure, positioning and ability to stay calm in difficult moments." } },
  // Defensores
  { number: 2, name: 'Nihad Mujakic', position: 'DF', age: 25, club: 'Gaziantep', bio: { "es": "Pocos jugadores en el equipo de Bosnia y Herzegovina han tomado un camino más extraño que Nihad Mujakic, quien de alguna manera terminó jugando para Sarajevo, Hajduk Split y Partizan Belgrado, tres clubes cuyos seguidores rara vez se ponen de acuerdo en algo más que el fútbol. Dentro de la selección de Bosnia probablemente se le entiende de forma diferente que fuera de ella. El seleccionador nacional, Sergej Barbarez, lo valora menos como un defensor pulido y más como un jugador capaz de afrontar los momentos incómodos sin pensar demasiado en ellos. Cada selección nacional tiende a tener al menos un futbolista por el que los aficionados discuten constantemente; Mujakic podría ser ese jugador para esta generación.", "en": "Few players in the Bosnia and Herzegovina squad have taken a stranger route than Nihad Mujakic, who has somehow ended up playing for Sarajevo, Hajduk Split and Partizan Belgrade, three clubs whose supporters rarely agree on anything beyond football mattering far too much. Inside the Bosnia squad he is probably understood differently than outside it. The national team coach, Sergej Barbarez, values him less as a polished defender and more as a player capable of handling uncomfortable moments without overthinking them. Every national team tends to carry at least one footballer the supporters argue about constantly - Mujakic might be that player for this generation." } },
  { number: 3, name: 'Dennis Hadzikadunic', position: 'DF', age: 27, club: 'Sampdoria', bio: { "es": "La carrera de Hadzikadunic se ha sentido inusualmente inestable para un jugador que todavía tiene veintitantos años. Desde que dejó Malmö por Rostov en 2018, ha pasado años moviéndose entre países y clubes casi temporada tras temporada, pasando por Suecia, Rusia, España y Alemania antes de llegar a Italia, en gran parte porque las regulaciones de la FIFA después de la invasión de Ucrania obligaron repetidamente a alejarse temporalmente de Rostov. En un momento admitió que se había cansado de adaptarse constantemente a nuevos vestuarios, entrenadores y ciudades. Nacido y criado en Malmö de padres bosnios, Hadzikadunic representó a Suecia en todos los niveles juveniles antes de finalmente optar por cambiar su lealtad a Bosnia y Herzegovina. Tranquilo con el balón y elegante en la posesión, durante mucho tiempo ha sido considerado uno de los defensores técnicamente más refinados en la configuración de la selección nacional.", "en": "Hadzikadunic’s career has felt unusually unsettled for a player still in his twenties. Since leaving Malmö for Rostov in 2018, he has spent years moving between countries and clubs almost season after season, passing through Sweden, Russia, Spain and Germany before arriving in Italy, largely because Fifa regulations after the invasion of Ukraine repeatedly forced temporary moves away from Rostov. At one stage he admitted he had grown tired of constantly adapting to new dressing rooms, coaches and cities. Born and raised in Malmö to Bosnian parents, Hadzikadunic represented Sweden at every youth level before eventually choosing to switch allegiance to Bosnia and Herzegovina. Calm on the ball and elegant in possession, he has long been viewed as one of the more technically refined defenders in the national team setup." } },
  { number: 4, name: 'Tarik Muharemovic', position: 'DF', age: 24, club: 'Sassuolo', bio: { "es": "Muharemovic habla cinco idiomas y se comporta con una tranquilidad que a menudo hace que la gente olvide lo joven que es en realidad. Nacido en Eslovenia de padres bosnios, criado en Austria y desarrollado en Italia, su historia se extiende ya por media Europa. Su ascenso ha sido sorprendentemente rápido: los ojeadores de la Juventus inicialmente viajaron a Austria para observar a otro jugador en el Wolfsberger, pero terminaron fichando a Muharemovic. Desde entonces, el defensa zurdo se ha convertido en uno de los jugadores jóvenes mejor valorados de Bosnia y Herzegovina, y se siente especialmente cómodo entrando en el centro del campo y haciendo avanzar el balón bajo presión. En Italia ya existe la sensación creciente de que una transferencia mucho mayor probablemente sea sólo cuestión de tiempo.", "en": "Muharemovic speaks five languages and carries himself with a calmness that often makes people forget how young he actually is. Born in Slovenia to Bosnian parents, raised in Austria and developed in Italy, his story already stretches across half of Europe. His rise has been remarkably fast: Juventus scouts initially travelled to Austria to watch another player at Wolfsberger, but ended up signing Muharemovic instead. Since then, the left-footed defender has developed into one of Bosnia and Herzegovina’s most highly-rated young players, notably comfortable stepping into midfield and progressing the ball under pressure. In Italy there is already a growing feeling that a much bigger transfer is probably only a matter of time." }, special: "Mature beyond his years" },
  { number: 5, name: 'Sead Kolasinac', position: 'DF', age: 32, club: 'Atalanta', bio: { "es": "Apodado \"El Tanque\", Kolasinac construyó su reputación sobre la base de la agresión, la lealtad y la dureza de la vieja escuela. Nacido en Karlsruhe de padres bosnios que huyeron de la guerra, trabajó como portero de un club nocturno cuando era adolescente mientras asistía a la academia del Schalke. At Schalke he became a cult figure because of his uncompromising style and connection with supporters, before later generating global news after confronting armed thieves during an attempted robbery involving his Arsenal teammate Mesut Özil in London in 2019. One of only two players in Bosnia and Herzegovina’s squad with previous World Cup experience, Kolasinac is also remembered for the unfortunate own goal he scored after just three minutes against Argentina at the Maracanã in the country’s primer partido en el torneo en 2014.", "en": "Nicknamed “The Tank”, Kolasinac built his reputation on aggression, loyalty and old-school toughness. Born in Karlsruhe to Bosnian parents who fled the war, he worked as a nightclub bouncer as a teenager while coming through Schalke’s academy. At Schalke he became a cult figure because of his uncompromising style and connection with supporters, before later generating global news after confronting armed thieves during an attempted robbery involving his Arsenal teammate Mesut Özil in London in 2019. One of only two players in Bosnia and Herzegovina’s squad with previous World Cup experience, Kolasinac is also remembered for the unfortunate own goal he scored after just three minutes against Argentina at the Maracanã in the country’s first-ever match at the tournament in 2014." }, special: "Former nightclub bouncer" },
  { number: 7, name: 'Amar Dedic', position: 'DF', age: 23, club: 'Benfica', bio: { "es": "Hay dos lados muy diferentes del personaje de Amar Dedic. Fuera del campo se muestra tranquilo, educado y ligeramente reservado; en él juega con constante agresividad e intensidad, siempre corriendo, presionando y exigiendo el balón. Los entrenadores han confiado en él desde muy pequeño por esa mentalidad. Nacido y criado en Austria en una familia bosnia que abandonó el país durante los años de la guerra, Dedic ha hablado a menudo de los sacrificios que hicieron sus padres mientras construían una nueva vida en el extranjero. El Salzburgo lo incorporó a su academia a los 13 años, y su viaje desde allí lo ha llevado a través de la Liga de Campeones y del Marsella al Benfica. A pesar de tener sólo 23 años, ya suma más de 25 partidos internacionales con Bosnia y Herzegovina y llega a este Mundial como uno de los líderes de una nueva generación.", "en": "There are two very different sides to Amar Dedic’s character. Off the pitch he comes across as calm, polite and slightly reserved; on it he plays with constant aggression and intensity, always sprinting, pressing and demanding the ball. Coaches have trusted him from a very young age because of that mentality. Born and raised in Austria to a Bosnian family that left the country during the war years, Dedic has often spoken about the sacrifices his parents made while building a new life abroad. Salzburg brought him into their academy at 13, and his journey from there has taken him through the Champions League and Marseille to Benfica. Despite still being only 23, he already has more than 25 caps for Bosnia and Herzegovina and enters this World Cup as one of the leaders of a new generation." } },
  { number: 18, name: 'Nikola Katic', position: 'DF', age: 29, club: 'Schalke', bio: { "es": "Durante la famosa victoria del Plymouth Argyle en la Copa FA sobre el Liverpool en 2025, Katic perdió un diente al principio del partido, siguió jugando y luego maldijo en vivo por televisión porque, como él mismo dijo: “Me encanta”. Probablemente fue el resumen perfecto del defensor que los aficionados de Bosnia y Herzegovina ya amaban. Alto, agresivo e intransigente, Katic pertenece a una generación de centrales que consideran la defensa como una batalla personal. Antes de elegir Bosnia en la categoría absoluta, representó a Croacia en categorías juveniles y desarrolló su carrera inicial en las ligas inferiores del fútbol croata antes de que Slaven Belupo le diera su gran avance. Más tarde, los Rangers lo contrataron durante la reconstrucción del club por parte de Steven Gerrard, donde su estilo físico rápidamente lo convirtió en un favorito de Ibrox.", "en": "During Plymouth Argyle’s famous FA Cup victory over Liverpool in 2025, Katic lost a tooth early in the game, kept playing and then swore live on television afterwards because, as he put it himself: “I fucking love it.” It was probably the perfect summary of the defender Bosnia and Herzegovina supporters had already grown to love. Tall, aggressive and uncompromising, Katic belongs to a generation of centre-backs that treats defending as a personal battle. Before choosing Bosnia at senior level, he represented Croatia in youth categories and built his early career through the lower leagues of Croatian football before Slaven Belupo gave him his breakthrough. Rangers later signed him during Steven Gerrard’s rebuild of the club, where his physical style quickly made him an Ibrox favourite." }, special: "Old-school" },
  { number: 21, name: 'Stjepan Radeljic', position: 'DF', age: 29, club: 'HNK Rijeka', bio: { "es": "Con 2,01 m de altura, Radeljic es imposible de ignorar en un campo de fútbol, ​​pero su carrera ha sido mucho menos sencilla de lo que sugiere su presencia física. Antes de establecerse en el más alto nivel, pasó años pasando por fútbol de reserva, cesiones y clubes más pequeños en Croacia, Alemania y Moldavia, sin que nunca se le viera como un gran prospecto. La paciencia finalmente dio sus frutos. Después de ayudar al Sheriff Tiraspol durante el período más exitoso de la historia del club, encontró una verdadera estabilidad en Rijeka, donde se convirtió en uno de los líderes del equipo que ganó el título croata en 2025. Aunque naturalmente asociado con los duelos aéreos y la defensa física debido a su altura, la reputación de Radeljic es la de un experto en posicionamiento, disciplina y consistencia.", "en": "At 2.01m tall, Radeljic is impossible to ignore on a football pitch, but his career has been much less straightforward than his physical presence suggests. Before establishing himself at the highest level, he spent years moving through reserve football, loans and smaller clubs in Croatia, Germany and Moldova, never really being seen as a major prospect. Patience eventually paid off. After helping Sheriff Tiraspol during the most successful period in the club’s history he found real stability at Rijeka, where he developed into one of the leaders of the side that won the Croatian title in 2025. Although naturally associated with aerial duels and physical defending because of his height, Radeljic’s reputation is as an expert in positioning, discipline and consistency." } },
  { number: 24, name: 'Nidal Celik', position: 'DF', age: 24, club: 'Lens', bio: { "es": "Antes incluso de cumplir 18 años, Celik ya llevaba el brazalete de capitán en Sarajevo, un club donde suele estar reservado para jugadores mayores con años a sus espaldas. Dentro del fútbol bosnio, esto fue tratado menos como un truco publicitario y más como una confirmación de algo que los entrenadores habían estado repitiendo silenciosamente durante años: que Celik se comportaba de manera diferente a la mayoría de los jugadores de su edad. Alto, tranquilo e inusualmente maduro en la posesión, pertenece a una generación de defensores bosnios formados tanto por el fútbol posicional moderno como por las viejas ideas balcánicas de dureza. Lens fichó por él a principios de 2025, lo que le convirtió en uno de los traspasos más caros de la historia de la liga bosnia. Para muchos seguidores, sin embargo, el detalle que más importaba era de dónde venía. Celik es un chico de Sarajevo en el sentido más puro: producto de la cantera, capitán y uno de los pocos grandes talentos de los últimos años que realmente se sintió vinculado al club antes de mudarse al extranjero.", "en": "Before he had even turned 18, Celik was wearing the captain’s armband at Sarajevo, a club where it is usually reserved for older players with years behind them. Inside Bosnian football that was treated less as a publicity stunt and more as confirmation of something coaches had been quietly repeating for years: that Celik carried himself differently from most players his age. Tall, calm and unusually mature in possession, he belongs to a generation of Bosnian defenders shaped as much by modern positional football as by old Balkan ideas of toughness. Lens moved for him in early 2025, making him one of the most expensive transfers in the history of the Bosnian league. For many supporters, though, the detail that mattered more was where he came from. Celik is a Sarajevo boy in the purest sense: academy product, captain, and one of the few major talents in recent years who genuinely felt tied to the club before moving abroad." }, special: "Next generation" },
  // Volantes
  { number: 6, name: 'Benjamin Tahirovic', position: 'MF', age: 23, club: 'Brøndby', bio: { "es": "El ascenso de Tahirović al fútbol de élite se produjo inusualmente rápido. Nacido en Suecia y de padres bosnios, pasó de las divisiones inferiores del fútbol sueco a la Roma de José Mourinho en tan solo unos años. Luego, el Ajax lo fichó como uno de los centrocampistas jóvenes mejor valorados de Europa. Pero su carrera ya ha tenido más turbulencias que las que la mayoría de los jugadores experimentan en una década. Después de períodos difíciles en Amsterdam y Dinamarca, inesperadamente se convirtió en parte de una controversia pública antes del repechaje de la Copa Mundial de Bosnia y Herzegovina contra Gales, cuando Sergej Barbarez afirmó que el entrenador galés del Brøndby, Steve Cooper, había conspirado intencionalmente para descartarlo del juego. Más tarde, Barbarez se disculpó con Cooper, quien de hecho había dejado al jugador por no \"estar a la altura de los valores\" del club danés, pero el episodio reveló lo importante que ya se había vuelto para la selección nacional a los 23 años.", "en": "Tahirović’s rise to elite football happened unusually fast. Born in Sweden to Bosnian parents, he went from the lower divisions of Swedish football to José Mourinho’s Roma in the space of only a few years. Ajax then signed him as one of Europe’s most highly-rated young midfielders. But his career has already contained more turbulence than most players experience in a decade. After difficult periods in Amsterdam and Denmark he unexpectedly became part of a public controversy before Bosnia and Herzegovina’s World Cup playoff against Wales, when Sergej Barbarez claimed Brøndby’s Welsh coach Steve Cooper had wilfully conspired to rule him out of the game. Barbarez later apologised to Cooper, who had in fact dropped the player for failing to “live up to the values” of the Danish club, but the episode revealed how important he had already become for the national team at 23." } },
  { number: 8, name: 'Armin Gigovic', position: 'MF', age: 24, club: 'Young Boys', bio: { "es": "Gigovic pasó la mayor parte de su carrera juvenil en la selección sueca, incluso capitaneando la selección sub-21, antes de decidir finalmente representar a Bosnia y Herzegovina en la categoría absoluta, a pesar de desarrollarse junto a una generación de suecos enormemente talentosa, que incluía nombres como Anthony Elanga, Lucas Bergvall y Roony Bardghji. Nacido en Lund de padres bosnios, se ganó una reputación gracias a la intensidad, la presión y las carreras constantes, más que a un fútbol espectacular. Su momento más importante con la camiseta de Bosnia llegó en Bucarest en marzo de 2025. Bosnia llegó a las eliminatorias para el Mundial sin una victoria en sus siete partidos anteriores y bajo una enorme presión después de años de decepciones. Gigovic marcó el único gol contra Rumanía, asegurando una de las victorias fuera de casa más llamativas de la selección nacional y cambiando el ambiente en el equipo casi de la noche a la mañana.", "en": "Gigovic spent most of his youth career in Sweden’s national setup, even captaining their Under-21s, before eventually deciding to represent Bosnia and Herzegovina at senior level, despite developing alongside a hugely talented generation of Swedes, including names such as Anthony Elanga, Lucas Bergvall and Roony Bardghji. Born in Lund to Bosnian parents, he built his reputation through intensity, pressing and constant running rather than spectacular football. His most important moment in a Bosnia shirt arrived in Bucharest in March 2025. Bosnia entered the World Cup qualifiers without a victory in their previous seven matches and under enormous pressure after years of disappointment. Gigovic scored the only goal against Romania, securing one of the national team’s most eye-catching away wins and changing the mood around the squad almost overnight." } },
  { number: 13, name: 'Ivan Basic', position: 'MF', age: 24, club: 'Astana', bio: { "es": "Basic era todavía un adolescente cuando la gente de su primer club, el Zrinjski Mostar, empezó a describirlo como “anticuado” en el mejor sentido posible, no por su aspecto o su forma de hablar, sino por su forma de entender el fútbol. Si bien muchos mediocampistas jóvenes disfrutan haciendo trucos o habilidades llamativas, Basic construyó su reputación perfeccionando el posicionamiento, la sincronización y un sentido inusual para controlar el ritmo. Desde entonces, su carrera ha tomado un rumbo que muy pocos jugadores bosnios imaginaban. Tras ganar el título bosnio con el Zrinjski, fichó por el Orenburg ruso durante uno de los periodos más extraños del fútbol europeo moderno, antes de continuar en Kazajistán con el Astana. Lejos del centro de atención de las grandes ligas, silenciosamente se convirtió en uno de los mediocampistas tácticamente más confiables de la nueva generación de Bosnia y Herzegovina.", "en": "Basic was still a teenager when people around his first club, Zrinjski Mostar, started describing him as “old-fashioned” in the best possible sense – not because of the way he looked or spoke, but because of the way he understood football. While many young midfielders enjoy rolling out tricks or flashy skills, Basic built his reputation through honing positioning, timing and an unusual sense for controlling rhythm. His career has since taken a route very few Bosnian players imagined for themselves. After winning the Bosnian title with Zrinjski, he moved to Russian side Orenburg during one of the strangest periods in modern European football, before later continuing in Kazakhstan with Astana. Away from the spotlight of major leagues, he quietly developed into one of the more tactically reliable midfielders of Bosnia and Herzegovina’s new generation." } },
  { number: 14, name: 'Ivan Sunjic', position: 'MF', age: 28, club: 'Pafos', bio: { "es": "Incluso antes de que Sunjic llegara a Inglaterra en 2019, cuando el Birmingham City pagó alrededor de £ 7 millones para llevarlo al campeonato, tenía la reputación de ser uno de los jugadores jóvenes más importantes del Dinamo Zagreb, capitán, internacional croata, mediocampista con juventud y experiencia en la Liga de Campeones. Sin embargo, en lugar de noches glamorosas de la Premier League, la mayor parte de sus siguientes cuatro años estuvieron definidos por luchas de supervivencia, caos gerencial y uno de los fútbol más exigentes físicamente de Europa. Nacido en Zenica y criado en Croacia, Sunjic cambió su alianza internacional de Croacia a Bosnia y Herzegovina en 2024. Para muchos seguidores, la medida fue simbólica, ya que un jugador que alguna vez fue visto como una parte clave del futuro de Croacia decidió jugar para Bosnia incluso cuando la selección nacional estaba en un período de renovación.", "en": "Even before Sunjic arrived in England in 2019, when Birmingham City paid around £7m to bring him to the Championship, he had the reputation of being one of Dinamo Zagreb’s most important young players, a captain, a Croatia international, a midfielder with youth and Champions League experience. Instead of glamorous Premier League nights, though, most of his next four years were defined by survival fights, managerial chaos and some of the most physically demanding football in Europe. Born in Zenica and raised in Croatia, Sunjic switched his international allegiance from Croatia to Bosnia and Herzegovina in 2024. For many supporters the move felt symbolic, as a player once seen as a key part of Croatia’s future chose instead to play for Bosnia even while the national team was in a period of renewal." } },
  { number: 16, name: 'Amir Hadziahmetovic', position: 'MF', age: 28, club: 'Hull City', bio: { "es": "Cuando Amir Hadziahmetovic se lesionó la rodilla durante la lucha del Hull City por los play-offs del campeonato bajo el mando de Sergej Jakirovic, inmediatamente surgieron temores de que su Copa del Mundo hubiera terminado. La Federación de Bosnia y Herzegovina confirmó públicamente que la lesión era grave, que se esperaba una cirugía y que la recuperación a tiempo para el torneo parecía imposible. Lo que hizo que su nombre apareciera en la lista final de convocados de Sergej Barbarez fuera una de las mayores sorpresas del anuncio. Barbarez explicó más tarde que los médicos creían que Hadziahmetovic aún podría recuperarse sin cirugía antes del Mundial, aunque con un riesgo significativo para su futuro a largo plazo. Eligió el torneo de todos modos. Esa decisión probablemente lo explica mejor que cualquier descripción táctica. Tranquilo e inteligente, aunque rara vez espectacular, Hadziahmetovic ha pasado la mayor parte de su carrera siendo apreciado más por los entrenadores que por las recopilaciones de momentos destacados. Desde que dejó Zeljeznicar para ir a Turquía cuando era adolescente, silenciosamente se convirtió en uno de los mediocampistas más disciplinados tácticamente de Bosnia.", "en": "When Amir Hadziahmetovic injured his knee during Hull City’s push for the Championship play-offs under Sergej Jakirovic, fears immediately flared that his World Cup was over. The Bosnia and Herzegovina FA publicly confirmed the injury was serious, surgery was expected and recovery in time for the tournament looked impossible. Which made his name appearing on Sergej Barbarez’s final squad list one of the biggest surprises of the announcement. Barbarez later explained that doctors believed Hadziahmetovic could still recover without surgery before the World Cup, though with significant risk for his long-term future. He chose the tournament anyway. That decision probably explains him better than any tactical description could. Calm and intelligent, if rarely spectacular, Hadziahmetovic has spent most of his career being appreciated more by coaches than by highlight compilations. Since leaving Zeljeznicar for Turkey as a teenager, he quietly developed into one of Bosnia’s most tactically disciplined midfielders." }, special: "Tactically disciplined" },
  { number: 17, name: 'Dzenis Burnic', position: 'MF', age: 26, club: 'Karlsruhe', bio: { "es": "La educación futbolística de Burnic tuvo lugar en el Borussia Dortmund, una de las academias más exigentes de Europa, donde fue considerado uno de los prospectos más prometedores del mediocampo del club durante su adolescencia. Ganó múltiples títulos juveniles con el Dortmund e hizo su debut en la Liga de Campeones con solo 18 años (una de las dos únicas apariciones en el primer equipo de los gigantes alemanes), pero su carrera senior se convirtió en algo mucho menos glamoroso de lo que muchos esperaban: préstamos, luchas por el descenso y constantes batallas por la estabilidad dieron forma a la primera mitad de su carrera. Nacido en Alemania de padres bosnios, Burnic representó a su tierra natal en las categorías inferiores antes de trasladarse a Bosnia y Herzegovina en 2024, fruto de muchos años de reflexión: tras recibir su primera convocatoria absoluta admitió que jugar en Bosnia era algo en lo que había pensado “desde pequeño”.", "en": "Burnic’s football education took place at Borussia Dortmund, one of Europe’s most demanding academies, where he was considered among the club’s more promising midfield prospects during his teenage years. He won multiple youth titles with Dortmund and made his Champions League debut at just 18 – one of only two first-team appearances for the German giants – but his senior career turned into something far less glamorous than many expected: loans, relegation fights and constant battles for stability shaped the first half of his career. Born in Germany to Bosnian parents, Burnic represented the land of his birth throughout the youth categories before switching to Bosnia and Herzegovina in 2024, the result of many years of consideration: after receiving his first senior call-up he admitted that playing for Bosnia had been something he had thought about “since childhood”." } },
  { number: 26, name: 'Ermin Mahmic', position: 'MF', age: 21, club: 'Slovan Liberec', bio: { "es": "Sólo unos días antes de que Sergej Barbarez anunciara el equipo de Bosnia y Herzegovina para la Copa del Mundo, Ermin Mahmic todavía era oficialmente un internacional juvenil de Austria. Luego vino otra exitosa operación nocturna de Barbarez y el director deportivo Emir Spahic, quienes convencieron al centrocampista del Slovan Liberec para que cambiara de bando justo a tiempo para el torneo. Lo que hizo que la historia fuera aún más inusual fue que Mahmic ya había cambiado de dirección una vez antes. Nacido y criado en Austria, representó brevemente a Bosnia en la categoría Sub-19 antes de regresar al sistema austriaco, para volver a hacerlo ahora. \"No se puede creer lo feliz y orgulloso que está de estar con nosotros\", dijo Barbarez después de que la FIFA aprobara el cambio. \"Tiene el perfil de un jugador que no tenemos mucho, un jugador que seguirá desarrollándose, con el objetivo de que Bosnia tenga buenos jugadores durante los próximos 10 años\".", "en": "Only a few days before Sergej Barbarez announced Bosnia and Herzegovina’s World Cup squad, Ermin Mahmic was still officially an Austria youth international. Then came one more successful late-night operation from Barbarez and sporting director Emir Spahic, who convinced the Slovan Liberec midfielder to switch allegiances just in time for the tournament. What made the story even more unusual was that Mahmic had already changed direction once before. Born and raised in Austria, he briefly represented Bosnia at Under-19 level before returning to Austria’s system, only to now switch back again. “You can’t believe how happy and proud he is to be with us,” Barbarez said after Fifa approved the change. “He has the profile of a player we don’t have much, a player who will continue to develop, with the aim that Bosnia will have good players for the next 10 years.”" }, special: "New recruit" },
  // Delanteros
  { number: 9, name: 'Samed Bazdar', position: 'FW', age: 22, club: 'Real Zaragoza', bio: { "es": "Los seguidores del Partizán comenzaron a llamar a Samed Bazdar “el nuevo Vlahovic” incluso antes de que cumpliera 18 años, momento en el que el Vlahovic original tenía sólo 22. Se informó que los cazatalentos de la Juventus lo siguieron cuando era adolescente, mientras que los medios serbios rápidamente construyeron la mitología balcánica habitual en torno a otro delantero alto y técnico que aparecía en Belgrado. El propio Bazdar bromeó una vez diciendo que estaba “molestando a la gente del Partizán” con constantes sesiones de entrenamiento extra, y añadió: “Así es como lo hacía también Dusan”. Después de representar a Serbia en todas las categorías inferiores e incluso hacer una aparición en la categoría absoluta, su decisión de mudarse a Bosnia y Herzegovina con Sergej Barbarez y Emir Spahic se convirtió en una de las historias más importantes de la selección nacional de la región. Técnicamente talentoso e impredecible, Bazdar pertenece a la generación que Bosnia espera que pueda ayudar a la selección nacional a recuperarse de la inevitable salida de Edin Dzeko, incluso si su carrera en el club recientemente ha perdido impulso después del revuelo inicial que lo rodea: ha sido titular ocasionalmente desde que llegó cedido al Jagiellonia Bialystok polaco en enero.", "en": "Partizan supporters started calling Samed Bazdar “the new Vlahovic” before he had even turned 18, at which point the original Vlahovic was himself only 22. Juventus scouts reportedly followed him as a teenager, while Serbian media quickly built the usual Balkan mythology around another tall, technical striker coming through at Belgrade. Bazdar himself once joked that he was “annoying people at Partizan” with constant extra training sessions, adding: “That’s how Dusan did it too.” After representing Serbia at every youth level and even making one senior appearance, his decision to switch to Bosnia and Herzegovina under Sergej Barbarez and Emir Spahic became one of the region’s biggest national-team stories. Technically gifted and unpredictable, Bazdar belongs to the generation Bosnia hopes can help the national team recover from the inevitable departure of Edin Dzeko, even if his club career has recently lost momentum after the early hype surrounding him – he has been only an occasional starter since joining Polish side Jagiellonia Bialystok on loan in January." } },
  { number: 10, name: 'Ermedin Demirovic', position: 'FW', age: 27, club: 'Stuttgart', bio: { "es": "Antes del repechaje para el Mundial de Bosnia y Herzegovina, Demirovic prometió en broma que compraría cerveza para todo el estadio de Stuttgart si su equipo se clasificaba. After they defeated Italy he actually followed through, standing behind the bar and personally serving free beer to supporters in Stuttgart. El gesto fue particularmente notable porque el propio Demirovic no bebe alcohol. “Soy un hombre de palabra”, dijo después. Nacido en Alemania de padres bosnios, Demirovic es uno de los pocos jugadores de su generación que representó a Bosnia y Herzegovina en todas las categorías inferiores antes de llegar finalmente a la selección absoluta. Su carrera en el club fue mucho menos sencilla de lo que muchos esperaban: fue liberado por el Hamburgo y fue cedido en Francia, España y Suiza antes de establecerse finalmente como uno de los delanteros más completos de la Bundesliga con el Augsburgo y el Stuttgart.", "en": "Before Bosnia and Herzegovina’s World Cup playoff Demirovic jokingly promised he would buy beer for the entire Stuttgart stadium if his side qualified. After they defeated Italy he actually followed through, standing behind the bar and personally serving free beer to supporters in Stuttgart. The gesture was particularly notable because Demirovic himself does not drink alcohol. “I’m a man of my word,” he said afterwards. Born in Germany to Bosnian parents, Demirovic is one of the rare players of his generation who represented Bosnia and Herzegovina at every single youth level before eventually reaching the senior national team. His club career was far less straightforward than many expected: released by Hamburg and pushed through loans in France, Spain and Switzerland before eventually establishing himself as one of the Bundesliga’s most complete forwards with Augsburg and Stuttgart." }, special: "Keeps promises" },
  { number: 11, name: 'Edin Dzeko', position: 'FW', age: 40, club: 'Schalke', captain: true, bio: { "es": "Mucho antes de convertirse en la figura definitoria de la historia del fútbol de Bosnia y Herzegovina, Zeljeznicar vendió a Dzeko al equipo checo Teplice por una tarifa relativamente pequeña porque pocas personas dentro del fútbol bosnio realmente creían que un delantero alto y físicamente subdesarrollado de Sarajevo podría convertirse en uno de los delanteros de élite de Europa. Había crecido jugando al fútbol entre edificios y refugios en Sarajevo durante la guerra, y luego describió el fútbol de esa época como “un escape de la realidad”. Lo que siguió se convirtió en la carrera más grande que haya producido el fútbol bosnio. Títulos de Bundesliga con el Wolfsburgo, triunfos de la Premier League con el Manchester City, capitanía en la Roma, finales de la Liga de Campeones con el Inter; Dzeko finalmente se convirtió en el máximo goleador y con más partidos jugados de todos los tiempos de Bosnia, y sigue siendo uno de sus jugadores clave a la edad de 40 años. Sin embargo, dentro de Bosnia, hace mucho tiempo que su importancia traspasó el fútbol mismo. Los jugadores más jóvenes del equipo de Sergej Barbarez a menudo hablan de él menos como un compañero de equipo y más como el punto de referencia de toda una generación.", "en": "Long before he became the defining figure in Bosnia and Herzegovina’s football history, Dzeko was sold by Zeljeznicar to Czech side Teplice for a relatively small fee because few people inside Bosnian football truly believed a tall, physically underdeveloped striker from Sarajevo could possibly become one of Europe’s elite forwards. He had grown up playing football between buildings and shelters in Sarajevo during the war, later describing football from that period as “an escape from reality”. What followed became the greatest career Bosnian football has produced. Bundesliga titles with Wolfsburg, Premier League triumphs with Manchester City, captaincy at Roma, Champions League finals with Inter; Dzeko eventually became Bosnia's all-time leading appearance-maker and record goalscorer, and remains one of their key players at the age of 40. Inside Bosnia, though, his importance long ago moved beyond football itself. Younger players in Sergej Barbarez’s squad often speak about him less as a teammate and more as the reference point of an entire generation." }, special: "All-time great" },
  { number: 15, name: 'Amar Memic', position: 'FW', age: 24, club: 'Viktoria Plzen', bio: { "es": "Hace sólo unos años, Memic jugaba en la segunda división del fútbol bosnio con Radnik Hadzici, lejos de los focos y de las conversaciones serias sobre la selección nacional. Su ascenso desde entonces ha sido rápido incluso para los estándares del fútbol moderno: Eslovenia, luego el fútbol checo, luego el Viktoria Plzen y la competición europea, todo en el espacio de cuatro años. La decisión de Sergej Barbarez de convocarlo para la selección absoluta en 2025 sorprendió inicialmente a muchos seguidores en Bosnia y Herzegovina. Pero dentro del equipo, Memic rápidamente se ganó el respeto por las cualidades que definen casi todo su juego: ritmo, carrera directa y energía implacable con y sin balón. Barbarez elogió su mentalidad y disposición para trabajar para el equipo, mientras que sus compañeros lo describen como una de las personalidades más fáciles de integrar en el vestuario.", "en": "Only a few years ago Memic was playing in the second tier of Bosnian football with Radnik Hadzici, far away from the spotlight or serious national-team conversations. His rise since then has been rapid even by modern football standards: Slovenia, then Czech football, then Viktoria Plzen and European competition, all in the space of four years. Sergej Barbarez’s decision to call him up for the senior national team in 2025 initially surprised many supporters in Bosnia and Herzegovina. But inside the squad, Memic quickly earned respect because of the qualities that define almost his entire game: pace, direct running and relentless energy with and without the ball. Barbarez praised his mentality and willingness to work for the team, while teammates describe him as one of the easier personalities to integrate into the dressing room." }, special: "Hard-working" },
  { number: 19, name: 'Kerim Alajbegovic', position: 'FW', age: 21, club: 'Bayer Leverkusen', bio: { "es": "Antes de que la mayoría de los seguidores de Bosnia y Herzegovina lo hubieran visto jugar un partido completo de la absoluta, ya se habían difundido en las redes sociales clips de las actuaciones de Alajbegovic. El entusiasmo solo creció después de que el Bayer Leverkusen, habiéndolo perfeccionado desde 2021, lo vendiera al Red Bull Salzburg el verano pasado y comenzara a jugar fútbol regular en el primer equipo senior por primera vez. Decir que brilló es quedarse corto: Alajbegovic fue nombrado el recién llegado de la temporada de la Bundesliga austriaca, y sus actuaciones fueron lo suficientemente buenas como para que Bayer activara su cláusula de recompra antes de finales de marzo. Simon Rolfes, su director deportivo, dijo que el jugador \"no sólo cumplió con las altas expectativas puestas en él en Salzburgo, sino que incluso las superó en muy poco tiempo\". Lo que ha sorprendido aún más que su talento es su total ausencia de miedo. A pesar de tener sólo 17 años, Sergej Barbarez confió en él para tirar los penaltis en las dos tandas de eliminatorias del Mundial, mientras que el propio Alajbegovic cambió el ritmo de ambos partidos tras entrar desde el banquillo. Dentro de Bosnia y Herzegovina ya se le considera no sólo como el mayor prospecto del país, sino también como una de las caras futuras de la selección nacional.", "en": "Before most supporters in Bosnia and Herzegovina had even seen him play a full senior match, clips of Alajbegovic’s performances had already spread across social media. The hype only grew after Bayer Leverkusen, having honed him since 2021, sold him to Red Bull Salzburg last summer and he started playing regular, senior first-team football for the first time. To say he shone is an understatement: Alajbegovic was named the Austrian Bundesliga’s newcomer of the season, his performances good enough for Bayer to trigger their buy-back clause before the end of March. Simon Rolfes, their managing director for sport, said the player had “not only fulfilled the high expectations placed in him in Salzburg, he has even exceeded them in a very short space of time”. What has surprised people even more than his talent is his complete absence of fear. Despite being only 17, Sergej Barbarez trusted him to take penalties in both World Cup playoff shootouts, while Alajbegovic himself changed the rhythm of both matches after entering from the bench. Inside Bosnia and Herzegovina he is already viewed not only as the country’s biggest prospect, but as one of the future faces of the national team." }, special: "Face of the future" },
  { number: 20, name: 'Esmir Bajraktarevic', position: 'FW', age: 20, club: 'PSV Eindhoven', bio: { "es": "Años antes de convertirse en uno de los mayores talentos de Bosnia y Herzegovina, un video casero filmado en Appleton, Wisconsin, mostraba a Bajraktarevic, de cinco años, jugando al fútbol en su patio trasero con una camiseta enorme de Edin Dzeko, celebrando después de meter el balón en una portería pequeña. El clip se volvió viral después de que Bajraktarevic eligiera Bosnia y Herzegovina en lugar de Estados Unidos en la categoría absoluta. “Cuando la gente me pregunta de dónde soy, digo que soy bosnio”, dijo Bajraktarević, cuyos padres llegaron a Estados Unidos después de huir del genocidio de Srebrenica. \"Crecí en una familia bosnia. Hablo bosnio con mis padres. Es mi sangre, son mis raíces\". Había algo poético en su debut internacional absoluto: saliendo del banquillo contra Holanda en 2024, en cinco minutos había preparado un gol para el propio Dzeko. Intrépido en situaciones uno contra uno y aparentemente inmune a la presión a pesar de su edad, rápidamente se convirtió en una de las caras de la nueva generación de Sergej Barbarez y anotó el penal decisivo en la victoria por penales sobre Italia que aseguró el lugar de Bosnia en la Copa del Mundo.", "en": "Years before he became one of Bosnia and Herzegovina’s biggest talents, a home video filmed in Appleton, Wisconsin showed a five-year-old Bajraktarevic playing football in his backyard wearing an outsized Edin Dzeko shirt, celebrating after putting the ball into a small goal. The clip went viral after Bajraktarevic chose Bosnia and Herzegovina over the United States at senior level. “When people ask me where I’m from, I say I’m Bosnian,” said Bajraktarević, whose parents reached America after fleeing the Srebrenica genocide. “I grew up in a Bosnian family. I speak Bosnian with my parents. It’s my blood, it’s my roots.” There was something poetic about his senior international debut: coming off the bench against the Netherlands in 2024, within five minutes he had set up a goal for Dzeko himself. Fearless in one-on-one situations and seemingly untouched by pressure despite his age, he quickly became one of the faces of Sergej Barbarez’s new generation, and scored the decisive penalty in the shootout victory over Italy that secured Bosnia’s place at the World Cup." }, special: "Proud Bosnian" },
  { number: 23, name: 'Haris Tabakovic', position: 'FW', age: 26, club: 'Borussia Mönchengladbach', bio: { "es": "La participación de Tabakovic en el Mundial quedó en duda en mayo cuando se fracturó un metatarsiano en un partido de liga contra el Hoffenheim. Inicialmente se supuso que tendría que retirarse, pero insistió en que \"está bien\" y \"viajará al Mundial\". A sus 31 años es una posibilidad que quizás no vuelva a tener. Nacido en Suiza de padres bosnios, pasó años pasando por equipos de reserva y transferencias fallidas, anotando goles en casi todas partes sin convencer a la gente de que pertenecía. Luego vino el gran avance que casi nadie esperaba: Tabaković, cuando tenía veintitantos años, de repente explotó en el Hertha Berlín, anotando 22 goles en 32 partidos y ganándose un pase al Borussia Mönchengladbach y, lo que es más importante, una convocatoria de Bosnia y Herzegovina. Pasaron casi dos años entre su debut y su primer gol internacional, pero luego anotó cuatro en cinco partidos, incluido el empate tardío contra Italia que, una tanda de penales más tarde, le valió a Bosnia su lugar en la Copa del Mundo.", "en": "Tabakovic’s participation in the World Cup was thrown into doubt in May when he fractured a metatarsal in a league game against Hoffenheim. It was initially assumed that he would have to withdraw, but he insisted he was “doing well” and “will travel to the World Cup”. At 31 it is a chance he may not get again. Born in Switzerland to Bosnian parents, he spent years moving through reserve teams and unsuccessful transfers, scoring goals almost everywhere without ever convincing people he belonged. Then came the breakthrough almost nobody expected: in his late twenties Tabaković suddenly exploded at Hertha Berlin, scoring 22 goals in 32 games and earning a move to Borussia Mönchengladbach and, more importantly, a Bosnia and Herzegovina call-up. Nearly two years elapsed between his debut and his first international goal but then got four in five games, including the late equaliser against Italy that, a penalty shootout later, earned Bosnia their World Cup place." } },
  { number: 25, name: 'Jovo Lukic', position: 'FW', age: 24, club: 'Universitatea Cluj', bio: { "es": "El camino de Lukic hacia la selección de Bosnia y Herzegovina para la Copa Mundial no ha sido nada sencillo. Si bien muchos jugadores ofensivos de su generación se desarrollaron tempranamente en el extranjero, él pasó años construyendo su carrera a través del fútbol bosnio antes de mudarse a Rumania en 2024, donde su primera temporada en la Universitatea Craiova fue un fracaso; sólo dos goles en 31 apariciones y crecientes dudas sobre si pertenecía a ese nivel. Entonces todo cambió de repente. Desde que se mudó a la Universitatea Cluj el verano pasado, la forma de Lukic se ha disparado, terminando la campaña como máximo goleador de Rumania y abriéndose camino en los planes de Sergej Barbarez. “Incluso si no juego, es muy importante para mí simplemente estar allí”, dijo. Lukic bromeó esta temporada diciendo que no había marcado un hat-trick “en cinco años” antes de finalmente hacerlo contra Hermannstadt en diciembre, dedicando los tres goles a su hijo pequeño y organizando una celebración que el niño había pedido.", "en": "Lukic’s path to the Bosnia and Herzegovina World Cup squad has been anything but straightforward. While many attacking players from his generation developed abroad early, he spent years building his career through Bosnian football before moving to Romania in 2024, where his first season at Universitatea Craiova was a failure; only two goals in 31 appearances and growing doubts about whether he belonged at that level. Then everything suddenly changed. Since moving to Universitatea Cluj last summer Lukic’s form has exploded, finishing the campaign as Romania’s top scorer and forcing his way into Sergej Barbarez’s plans. “Even if I don’t play, it’s a big thing for me just to be there,” he said. Lukic joked this season that he had not scored a hat-trick “for five years” before finally doing it against Hermannstadt in December, dedicating all three goals to his young son and wheeling out a celebration the boy had asked for." } },
];

export const lineup = {
  formation: '4-2-3-1',
  startingXI: [1, 5, 18, 3, 7, 6, 16, 20, 8, 10, 11]
};
